# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İKİ KAT AÇI (YARIM AÇI) FORMÜLLERİ: SİNÜS VE KOSİNÜS</text>\n  <rect x="25" y="46" width="315" height="196" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Sinüs İki Kat Açı Özdeşliği</text>\n  <rect x="45" y="84" width="275" height="44" rx="8" fill="#ffffff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="182" y="112" text-anchor="middle" font-size="16" font-weight="bold" fill="#1d4ed8">sin(2x) = 2 · sin(x) · cos(x)</text>\n  <text x="42" y="150" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Yarım Açı Biçimi:</tspan> sin(x) = 2 · sin(x/2) · cos(x/2)</text>\n  <text x="42" y="174" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Tam Kare Özdeşliği:</tspan></text>\n  <text x="52" y="192" font-size="11.5" font-weight="bold" fill="#1d4ed8">(sin(x) ± cos(x))² = 1 ± sin(2x)</text>\n  <text x="42" y="218" font-size="11" fill="#1e3a8a">• Örnek: 2·sin(15°)·cos(15°) = sin(30°) = 1/2</text>\n  <rect x="360" y="46" width="315" height="196" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Kosinüs İki Kat Açı Özdeşlikleri (3 Biçim)</text>\n  <rect x="378" y="82" width="280" height="36" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="517" y="105" text-anchor="middle" font-size="14" font-weight="bold" fill="#15803d">1) cos(2x) = cos²(x) - sin²(x)</text>\n  <rect x="378" y="126" width="280" height="36" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="517" y="149" text-anchor="middle" font-size="14" font-weight="bold" fill="#15803d">2) cos(2x) = 2·cos²(x) - 1</text>\n  <rect x="378" y="170" width="280" height="36" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="517" y="193" text-anchor="middle" font-size="14" font-weight="bold" fill="#15803d">3) cos(2x) = 1 - 2·sin²(x)</text>\n  <text x="517" y="226" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">1 + cos(2x) = 2·cos²(x)  ·  1 - cos(2x) = 2·sin²(x)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TANJANT VE KOTANJANT İKİ KAT AÇI ÖZDEŞLİKLERİ</text>\n  <rect x="25" y="46" width="315" height="196" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="182" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">Tanjant İki Kat Açı Bağıntısı</text>\n  <rect x="45" y="84" width="275" height="52" rx="8" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="182" y="116" text-anchor="middle" font-size="15" font-weight="bold" fill="#b45309">tan(2x) = (2 · tan(x)) / (1 - tan²(x))</text>\n  <text x="42" y="160" font-size="11.5" fill="#78350f">• sin(x+x) ve cos(x+x) toplam formüllerinde</text>\n  <text x="50" y="176" font-size="11.5" fill="#78350f">a = b = x yazılarak elde edilir.</text>\n  <text x="42" y="200" font-size="11.5" fill="#78350f">• <tspan font-weight="bold">Örnek:</tspan> tan(x) = 1/2 ise</text>\n  <text x="50" y="218" font-size="11.5" font-weight="bold" fill="#92400e">tan(2x) = (2·(1/2)) / (1 - 1/4) = 1 / (3/4) = 4/3</text>\n  <rect x="360" y="46" width="315" height="196" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">Kotanjant İki Kat Açı Bağıntısı</text>\n  <rect x="378" y="84" width="280" height="52" rx="8" fill="#ffffff" stroke="#c084fc" stroke-width="1.5"/>\n  <text x="517" y="116" text-anchor="middle" font-size="15" font-weight="bold" fill="#7e22ce">cot(2x) = (cot²(x) - 1) / (2 · cot(x))</text>\n  <text x="378" y="160" font-size="11.5" fill="#581c87">• <tspan font-weight="bold">Pratik Yol:</tspan> cot(2x) = 1 / tan(2x) olduğundan</text>\n  <text x="386" y="176" font-size="11.5" fill="#581c87">önce tan(2x) bulunup çarpmaya göre tersi alınır.</text>\n  <text x="378" y="200" font-size="11.5" fill="#581c87">• <tspan font-weight="bold">Yarım Açı Üçgeni:</tspan> 2x açılı dik üçgende</text>\n  <text x="386" y="218" font-size="11.5" font-weight="bold" fill="#6b21a8">hipotenüs kadar uzatılarak (x, x) ikizkenarı kurulur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">2x AÇISINDAN x AÇISINA GEÇİŞ (İKİZKENAR ÜÇGEN YÖNTEMİ)</text>\n  <rect x="25" y="46" width="365" height="196" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="207" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">ABC Dik Üçgenine ACD İkizkenar Üçgeni Ekleme</text>\n  <polygon points="80,200 220,200 80,95" fill="#dbeafe" stroke="#1d4ed8" stroke-width="2.5"/>\n  <polygon points="220,200 355,200 80,95" fill="#dcfce7" stroke="#16a34a" stroke-width="2" stroke-dasharray="5,3"/>\n  <rect x="80" y="186" width="14" height="14" fill="none" stroke="#1d4ed8" stroke-width="1.5"/>\n  <text x="65" y="205" font-size="12" font-weight="bold" fill="#1e3a8a">B</text>\n  <text x="72" y="86" font-size="12" font-weight="bold" fill="#1e3a8a">A</text>\n  <text x="218" y="218" font-size="12" font-weight="bold" fill="#1e3a8a">C</text>\n  <text x="355" y="218" font-size="12" font-weight="bold" fill="#166534">D</text>\n  <text x="182" y="194" font-size="11" font-weight="bold" fill="#dc2626">2x</text>\n  <text x="305" y="194" font-size="11" font-weight="bold" fill="#15803d">x</text>\n  <text x="145" y="118" font-size="11" font-weight="bold" fill="#15803d">x</text>\n  <text x="58" y="152" font-size="12" font-weight="bold" fill="#1d4ed8">3</text>\n  <text x="145" y="216" font-size="12" font-weight="bold" fill="#1d4ed8">4</text>\n  <text x="148" y="142" font-size="12" font-weight="bold" fill="#dc2626">5</text>\n  <text x="285" y="216" font-size="12" font-weight="bold" fill="#166534">5</text>\n  <rect x="405" y="46" width="270" height="196" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="540" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">Adım Adım Geometrik Çözüm</text>\n  <text x="420" y="96" font-size="11" fill="#78350f">1. tan(2x) = 3/4 ise ABC dik</text>\n  <text x="428" y="112" font-size="11" fill="#78350f">üçgeni (3-4-5) çizilir.</text>\n  <text x="420" y="136" font-size="11" fill="#78350f">2. [BC] kenarı hipotenüs (|AC| = 5)</text>\n  <text x="428" y="152" font-size="11" fill="#78350f">kadar uzatılarak |CD| = 5 alınır.</text>\n  <text x="420" y="176" font-size="11" fill="#78350f">3. İki iç açının toplamı komşu olmayan</text>\n  <text x="428" y="192" font-size="11" fill="#78350f">dış açıya (2x) eşit olduğundan D = x olur.</text>\n  <rect x="420" y="202" width="240" height="28" rx="6" fill="#ffffff" stroke="#f59e0b"/>\n  <text x="540" y="220" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#b45309">ABD üçgeninde: tan(x) = 3 / (4+5) = 1/3</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
